#  ENCODER
# ===========================================================================
def n_units_of(obs, player):
    """How many units this seat controls this turn (capped at UNITS_MAX)."""
    farm = obs["farms"][player]
    return min(UNITS_MAX, 1 + len(farm.get("hands") or ()))


def unit_positions(obs, player):
    """[(x, y)] for unit 0..n_units-1 -- index 0 is the main farmer."""
    farm = obs["farms"][player]
    out = [tuple(farm["farmer"])]
    for h in (farm.get("hands") or ()):
        if len(out) >= UNITS_MAX:
            break
        out.append(tuple(h))
    return out


def step_of(obs):
    """`step` is absent on seat 1 in replays; the framework value is day*24+hour."""
    s = obs.get("step")
    if s is None:
        s = obs.get("day", 0) * TURNS_PER_DAY + obs.get("hour", 0)
    return s


def encode_obs_py(obs, player=None):
    """obs -> (grid, units, glob).

    grid  : 100 rows of GRID_C floats, row-major tile index y*10+x
    units : UNITS_MAX rows of UNIT_F_N floats (inactive units are zeroed)
    glob  : GLOB_N floats

    Plain nested lists of Python floats -- the exported submission calls this
    once per step, `native/src/encode.rs` reproduces it to 1e-6.
    """
    if player is None:
        player = obs["player"]
    farms = obs["farms"]
    me = farms[player]
    opp = farms[1 - player]
    priv = obs["private"]
    day = obs.get("day", 0)
    hour = obs.get("hour", 0)
    step = step_of(obs)
    tiles = me["tiles"]

    shed = priv.get("shed") or {}
    seeds = priv.get("seeds") or {}
    invs = priv.get("inventories") or [{}]
    mkt = obs.get("market") or {}
    minv = mkt.get("inventory") or {}
    prices = mkt.get("prices") or {}
    shops = (obs.get("town") or {}).get("unlocked_shops") or ()

    # ---------------------------------------------------------------- units
    pos = unit_positions(obs, player)
    n_units = len(pos)
    crowd = {}
    for p in pos:
        crowd[p] = crowd.get(p, 0) + 1

    units = []
    for u in range(UNITS_MAX):
        row = [0.0] * UNIT_F_N
        row[16] = u / 16.0
        if u < n_units:
            x, y = pos[u]
            flat = y * BOARD + x
            inv = invs[u] if u < len(invs) else {}
            row[0] = x / 10.0
            row[1] = y / 10.0
            row[2] = DIST_SHED[flat] / 10.0
            tot = 0
            for i, it in enumerate(ITEMS12):
                n = inv.get(it, 0)
                if n:
                    tot += n
                    row[3 + i] = (n if n < 20 else 20) / 20.0
            row[15] = 1.0 if u == 0 else 0.0
            row[17] = 1.0
            row[18] = 1.0 if (x, y) in SHED_SET else 0.0
            row[19] = (tot if tot < 20 else 20) / 20.0
            row[20] = 1.0 if inv.get("FERTILIZER", 0) > 0 else 0.0
            row[21] = 1.0 if inv.get("WHEAT", 0) > 0 else 0.0
            row[22] = 1.0 if (inv.get("GOOSE", 0) or inv.get("COW", 0)
                              or inv.get("SHEEP", 0)) else 0.0
            row[23] = (x - 4.5) / 10.0
            row[24] = (y - 4.5) / 10.0
            c = crowd[(x, y)] - 1
            row[25] = (c if c < 3 else 3) / 3.0
        units.append(row)

    # ----------------------------------------------------------------- grid
    grid = []
    my_crop = [0] * 5
    my_anim = [0] * 3
    my_used = 0
    my_empty = 0
    unit_count = [0] * N_TILES
    for (x, y) in pos:
        unit_count[y * BOARD + x] += 1
    t = 0
    for y in range(BOARD):
        row_tiles = tiles[y]
        for x in range(BOARD):
            g = [0.0] * GRID_C
            tile = row_tiles[x]
            if t in SHED_FLAT:
                g[23] = 1.0
            n_here = unit_count[t]
            if n_here:
                g[24] = (n_here if n_here < 4 else 4) / 4.0
            if tile == "LOCKED":
                g[1] = 1.0
            else:
                g[25] = 1.0
                if tile is None:
                    g[0] = 1.0
                    my_empty += 1
                else:
                    my_used += 1
                    kind = tile.get("kind")
                    if kind == "WEED":
                        g[2] = 1.0
                    elif kind == "PLANT":
                        g[3] = 1.0
                        crop = tile.get("crop")
                        ci = CROP_IDX.get(crop)
                        if ci is not None:
                            g[6 + ci] = 1.0
                            my_crop[ci] += 1
                        yu = tile.get("yield_units", 0)
                        g[14] = (yu if yu < 6 else 6) / 6.0
                        g[15] = 1.0 if tile.get("watered_today") else 0.0
                        cu = tile.get("consecutive_unwatered", 0)
                        g[16] = (cu if cu < 2 else 2) / 2.0
                        fert_days = tile.get("fertilized_until_day", -1) - day + 1
                        if fert_days > 0:
                            g[17] = (fert_days if fert_days < 3 else 3) / 3.0
                        age = day - tile.get("planted_day", day)
                        if age < 0:
                            age = 0
                        g[18] = (age if age < 12 else 12) / 12.0
                        if ci is not None:
                            d2 = crop_days_to_next(crop, age)
                            g[19] = (d2 if d2 < 6 else 6) / 6.0
                        mls = tile.get("max_lifespan_step", -1)
                        if mls is not None and mls >= 0:
                            # `_decay_plants` strips a yield unit every 2 steps
                            # from max_lifespan_step on, then the tile weeds over
                            v = 1.0 - (mls - step) / 48.0
                            g[20] = 0.0 if v < 0.0 else (1.0 if v > 1.0 else v)
                    else:                                   # COOP / PASTURE
                        animal = tile.get("animal")
                        if animal is None:
                            g[4] = 1.0
                            if kind == "COOP":
                                g[11] = 1.0                  # accepts GOOSE
                            else:
                                g[12] = 1.0                  # accepts COW
                                g[13] = 1.0                  # accepts SHEEP
                        else:
                            g[5] = 1.0
                            ai = ANIMAL_IDX.get(animal)
                            if ai is not None:
                                g[11 + ai] = 1.0
                                my_anim[ai] += 1
                            yu = tile.get("yield_units", 0)
                            g[14] = (yu if yu < 6 else 6) / 6.0
                            cu = tile.get("consecutive_unfed", 0)
                            g[16] = (cu if cu < 2 else 2) / 2.0
                            bank = tile.get("pending_care_bonus", 0) or 0
                            g[17] = (bank if bank < 3 else 3) / 3.0
                            age = day - tile.get("placed_day", day)
                            if age < 0:
                                age = 0
                            g[18] = (age if age < 12 else 12) / 12.0
                            if ai is not None:
                                d2 = animal_days_to_next(animal, age)
                                g[19] = (d2 if d2 < 6 else 6) / 6.0
                            g[20] = 1.0 if tile.get("fed_today") else 0.0
                            g[21] = 1.0 if tile.get("cared_today") else 0.0
                            g[22] = 1.0 if tile.get("fertilizer_available") else 0.0
            grid.append(g)
            t += 1

    # ----------------------------------------------------------------- glob
    money = float(me.get("money", 0.0))
    omoney = float(opp.get("money", 0.0))
    glob = [0.0] * GLOB_N
    glob[0] = day / 30.0
    ang = 2.0 * math.pi * hour / TURNS_PER_DAY
    glob[1] = math.sin(ang)
    glob[2] = math.cos(ang)
    glob[3] = step / 719.0
    glob[4] = (LAST_DAY - day) / 30.0
    glob[5] = math.log1p(abs(money)) / 10.0 * (1.0 if money >= 0 else -1.0)
    glob[6] = math.log1p(abs(omoney)) / 10.0 * (1.0 if omoney >= 0 else -1.0)
    glob[7] = (money - omoney) / (abs(money) + abs(omoney) + 1000.0)

    shed_total = 0
    for i, it in enumerate(ITEMS12):
        n = shed.get(it, 0)
        shed_total += n
        glob[8 + i] = n / 100.0
    for i, c in enumerate(CROP_LIST):
        glob[20 + i] = seeds.get(c, 0) / 20.0

    liq = 0.0
    for i, p in enumerate(PRODUCTS):
        inv_p = minv.get(p, MARKET_I0)
        pr = prices.get(p)
        if pr is None:
            pr = market_price(p, inv_p)
        glob[25 + i] = (inv_p - MARKET_I0) / float(T_ANCHOR[p])
        glob[34 + i] = pr / float(BASE[p])
        glob[43 + i] = 1.0 if pr <= PRICE_FLOOR else 0.0
        held = shed.get(p, 0)
        for iv in invs:
            held += iv.get(p, 0)
        if held:
            liq += liquidation_value(p, held, inv_p)

    if shops:
        counts = {}
        for s in shops:
            counts[s] = counts.get(s, 0) + 1
        for i, s in enumerate(SHOP_NAMES):
            glob[52 + i] = counts.get(s, 0) / 4.0

    quads = me.get("unlocked_quadrants") or ("NW",)
    qset = set(quads)
    for i, q in enumerate(QUADS):
        glob[60 + i] = 1.0 if q in qset else 0.0
    n_hands = len(me.get("hands") or ())
    glob[64] = n_hands / 16.0
    hires_today = me.get("hires_today", 0)
    glob[65] = hires_today / 16.0
    hc = hire_cost(hires_today)
    glob[66] = (hc if hc < 1000 else 1000) / 100.0
    n_extra = len(quads) - 1
    glob[67] = (LAND_PRICES[n_extra] / 4000.0) if 0 <= n_extra < len(LAND_PRICES) else 0.0
    glob[68] = shed_total / 100.0
    glob[69] = liq / 10000.0

    for i in range(5):
        glob[70 + i] = my_crop[i] / 25.0
    for i in range(3):
        glob[75 + i] = my_anim[i] / 16.0
    glob[78] = my_used / 100.0
    glob[79] = my_empty / 100.0

    # opponent census (coarse; the opponent farm is fully visible)
    o_crop = [0] * 5
    o_anim = [0] * 3
    o_struct = o_used = o_weeds = o_empty = o_locked = 0
    for row_tiles in opp["tiles"]:
        for tile in row_tiles:
            if tile == "LOCKED":
                o_locked += 1
            elif tile is None:
                o_empty += 1
            else:
                o_used += 1
                kind = tile.get("kind")
                if kind == "WEED":
                    o_weeds += 1
                elif kind == "PLANT":
                    ci = CROP_IDX.get(tile.get("crop"))
                    if ci is not None:
                        o_crop[ci] += 1
                else:
                    a = tile.get("animal")
                    if a is None:
                        o_struct += 1
                    else:
                        ai = ANIMAL_IDX.get(a)
                        if ai is not None:
                            o_anim[ai] += 1
    for i in range(5):
        glob[80 + i] = o_crop[i] / 25.0
    for i in range(3):
        glob[85 + i] = o_anim[i] / 16.0
    glob[88] = o_struct / 16.0
    glob[89] = o_used / 100.0
    glob[90] = o_weeds / 25.0
    glob[91] = o_empty / 100.0
    glob[92] = o_locked / 100.0
    glob[93] = len(opp.get("hands") or ()) / 16.0
    glob[94] = len(opp.get("unlocked_quadrants") or ("NW",)) / 4.0
    glob[95] = opp.get("hires_today", 0) / 16.0

    return grid, units, glob


# ===========================================================================
#  LEGALITY MASKS  (staged: target -> op -> item -> qty)
# ===========================================================================
def tile_caps(obs, player, flat):
    """Tile-only half of the op mask: [N_OPS] of 0/1.

    Mirrors `engine._apply_unit_action`'s guards exactly, including the two
    that surprise: shed ops resolve BEFORE the LOCKED guard (so DROP / PICKUP /
    PLACE_SHED work from a locked shed-access tile), and everything else
    requires an owned tile.
    """
    m = [0] * N_OPS
    m[0] = 1                                            # PASS is always legal
    x = flat % BOARD
    y = flat // BOARD
    tile = obs["farms"][player]["tiles"][y][x]
    day = obs.get("day", 0)
    if flat in SHED_FLAT:
        m[12] = 1        # DROP
        m[13] = 1        # PICKUP
        m[16] = 1        # PLACE_SHED
    if tile == "LOCKED":
        return m
    if tile is None:
        m[1] = 1         # PLANT
        m[7] = 1         # BUILD_COOP
        m[8] = 1         # BUILD_PASTURE
        return m
    kind = tile.get("kind")
    if kind == "PLANT":
        m[6] = 1                                        # DIG
        if not tile.get("watered_today"):
            m[2] = 1                                    # WATER
        yu = tile.get("yield_units", 0)
        crop = tile.get("crop")
        sched = CROP_SCHED.get(crop)
        if yu > 0 and sched is not None and \
                (day - tile.get("planted_day", day)) >= sched[0]:
            m[3] = 1                                    # HARVEST_CROP
        m[5] = 1                                        # FERTILIZE
    elif kind == "WEED":
        m[6] = 1                                        # DIG
    elif kind in ("COOP", "PASTURE"):
        if tile.get("animal") is None:
            m[6] = 1                                    # DIG (empty structure)
            if kind == "COOP":
                m[14] = 1                               # PLACE_COOP
            else:
                m[15] = 1                               # PLACE_PASTURE
        else:
            if tile.get("yield_units", 0) > 0:
                m[4] = 1                                # HARVEST_ANIMAL
            if not tile.get("fed_today"):
                m[9] = 1                                # FEED
            if not tile.get("cared_today"):
                m[10] = 1                               # CARE
            if tile.get("fertilizer_available"):
                m[11] = 1                               # COLLECT_FERTILIZER
    return m


def unit_caps(obs, player, u):
    """Unit-only half of the op mask: [N_OPS] of 0/1 (inventory / seeds / shed)."""
    m = [1] * N_OPS
    priv = obs["private"]
    invs = priv.get("inventories") or [{}]
    inv = invs[u] if u < len(invs) else {}
    seeds = priv.get("seeds") or {}
    shed = priv.get("shed") or {}
    carry = sum(v for v in inv.values() if v > 0)
    m[1] = 1 if any(seeds.get(c, 0) > 0 for c in CROP_LIST) else 0   # PLANT
    m[5] = 1 if inv.get("FERTILIZER", 0) > 0 else 0                  # FERTILIZE
    m[9] = 1 if inv.get("WHEAT", 0) > 0 else 0                       # FEED
    m[12] = 1 if carry > 0 else 0                                    # DROP
    m[13] = 1 if any(shed.get(i, 0) > 0 for i in ITEMS12) else 0     # PICKUP
    m[14] = 1 if inv.get("GOOSE", 0) > 0 else 0                      # PLACE_COOP
    m[15] = 1 if (inv.get("COW", 0) > 0 or inv.get("SHEEP", 0) > 0) else 0
    m[16] = 1 if carry > 0 else 0                                    # PLACE_SHED
    return m


def op_mask_for_tile(obs, player, unit_idx, tile):
    """[N_OPS] 0/1 -- what unit `unit_idx` could legally do standing on `tile`.

    `tile` is a flat index y*10+x (a (x, y) tuple is also accepted).  This is
    the authoritative predicate; `tile_caps` * `unit_caps` is the factorized
    fast path and must agree with it exactly (rl2/difftest.py checks that).
    """
    if isinstance(tile, (tuple, list)):
        tile = tile[1] * BOARD + tile[0]
    tc = tile_caps(obs, player, tile)
    uc = unit_caps(obs, player, unit_idx)
    return [a & b for a, b in zip(tc, uc)]


def item_mask_for(obs, player, unit_idx, tile, op):
    """[N_ITEMS] 0/1 -- legal `item` values for this (unit, tile, op)."""
    m = [0] * N_ITEMS
    kind = OP_ITEM_KIND[op]
    if kind == "none":
        m[0] = 1
        return m
    if kind == "wheat":
        m[IDX_WHEAT] = 1
        return m
    if kind == "fert":
        m[IDX_FERTILIZER] = 1
        return m
    priv = obs["private"]
    if kind == "seed":
        seeds = priv.get("seeds") or {}
        for i, c in enumerate(CROP_LIST):
            if seeds.get(c, 0) > 0:
                m[i] = 1
    elif kind == "shed":
        shed = priv.get("shed") or {}
        for i, it in enumerate(ITEMS12):
            if shed.get(it, 0) > 0:
                m[i] = 1
    elif kind == "carry":
        invs = priv.get("inventories") or [{}]
        inv = invs[unit_idx] if unit_idx < len(invs) else {}
        for i, it in enumerate(ITEMS12):
            if inv.get(it, 0) > 0:
                m[i] = 1
    elif kind == "coop":
        invs = priv.get("inventories") or [{}]
        inv = invs[unit_idx] if unit_idx < len(invs) else {}
        if inv.get("GOOSE", 0) > 0:
            m[IDX_GOOSE] = 1
    elif kind == "pasture":
        invs = priv.get("inventories") or [{}]
        inv = invs[unit_idx] if unit_idx < len(invs) else {}
        if inv.get("COW", 0) > 0:
            m[IDX_COW] = 1
        if inv.get("SHEEP", 0) > 0:
            m[IDX_SHEEP] = 1
    if not any(m):
        m[0] = 1                 # never hand an all-zero row to a softmax
    return m


def qty_mask_for(obs, player, unit_idx, tile, op, item):
    """[N_QTY] 0/1 -- legal `qty` bins.  Ops without a quantity allow bin 0 only."""
    m = [0] * N_QTY
    if not OP_USES_QTY[op]:
        m[0] = 1
        return m
    priv = obs["private"]
    name = ITEMS12[item]
    if op == 13:                                        # PICKUP: from the shed
        have = (priv.get("shed") or {}).get(name, 0)
    else:                                               # PLACE_SHED: from the unit
        invs = priv.get("inventories") or [{}]
        inv = invs[unit_idx] if unit_idx < len(invs) else {}
        have = inv.get(name, 0)
    _fill_qty_mask(m, QTY_BINS, have)
    return m


def _fill_qty_mask(m, bins, have):
    """Shared bin legality: numeric bins need the stock, HALF needs >= 2."""
    for i, q in enumerate(bins):
        if q == "ALL":
            m[i] = 1 if have > 0 else 0
        elif q == "HALF":
            m[i] = 1 if have >= 2 else 0
        elif have >= q:
            m[i] = 1
    if not any(m):
        m[0] = 1
    return m


def market_shed_upper(obs, player):
    """Upper bound on the shed and the cash the market will see THIS step.

    The engine applies every unit action before `_process_market`, and commits
    market order *i* completely before order *i+1*.  So "sell what I drop this
    step" and "buy with what I just sold" are both legal, and a mask taken from
    the pre-action shed and pre-sale cash forbids them -- it was making the
    tape's own +1.7k sell-what-you-drop pattern unreachable and throwing away
    every BC label that used it.

    Masks are LOCAL and must never forbid a legal action, so this is a bound,
    not a simulation: the shed gains everything the units are carrying (capped
    at `shedCapacity`) and the cash gains the liquidation value of the result.
    Over-permitting is safe -- `decode_actions_py`'s `MarketShadow` is exact
    and repairs anything the policy cannot actually afford.
    """
    priv = obs["private"]
    shed = dict(priv.get("shed") or {})
    for inv in (priv.get("inventories") or ()):
        for it, n in inv.items():
            if n > 0:
                shed[it] = shed.get(it, 0) + n
    total = sum(v for v in shed.values() if v > 0)
    if total > SHED_CAPACITY:
        # cap the bound, keeping the largest stacks (order is irrelevant to a
        # bound, but the total has to stay inside the shed)
        total = SHED_CAPACITY
    minv = (obs.get("market") or {}).get("inventory") or {}
    money = float(obs["farms"][player].get("money", 0.0))
    for p in PRODUCTS:
        n = shed.get(p, 0)
        if n > 0:
            money += liquidation_value(p, n, minv.get(p, MARKET_I0))
    return shed, money, total


def _v2_buy_bonus(obs, name, money, room):
    """v2 only: units of `name` a BUY_PRODUCT could add to the shed this step.

    With the v2 decode a buy lands in the shed before a later slot's SELL, so
    the SELL masks must not forbid selling a product the seat can afford to
    buy -- otherwise the round trip is expressible but the policy is not
    allowed to say it.  Quoted at the first unit's price, which UNDERSTATES
    the cost of later units, so this is an upper bound (masks may over-permit;
    `MarketShadow` is the exact authority).
    """
    if MARKET_QTY_MODE != "v2" or name not in BUYABLE_PRODUCTS or room <= 0:
        return 0
    if name not in PRODUCTS or money <= 0:
        return 0
    minv = (obs.get("market") or {}).get("inventory") or {}
    p = market_price(name, minv.get(name, MARKET_I0) - 1)
    if p <= 0:
        return 0
    n = int(money // p)
    return n if n < int(room) else int(room)


def _market_op_mask(obs, player):
    farm = obs["farms"][player]
    shed, money, shed_total = market_shed_upper(obs, player)
    room = shed_total < SHED_CAPACITY
    mkt = obs.get("market") or {}
    prices = mkt.get("prices") or {}
    minv = mkt.get("inventory") or {}
    m = [0] * N_MKT_OPS
    m[0] = 1                                                     # NONE
    m[1] = 1 if any(shed.get(p, 0) > 0 for p in PRODUCTS) else 0  # SELL
    m[2] = 1 if money >= min(SEED_COST.values()) else 0           # BUY_SEED
    if room:
        cheapest = min(
            (prices.get(p) if prices.get(p) is not None
             else market_price(p, minv.get(p, MARKET_I0) - 1))
            for p in BUYABLE_PRODUCTS)
        m[3] = 1 if money >= cheapest else 0                      # BUY_PRODUCT
        m[4] = 1 if money >= min(ANIMAL_COST.values()) else 0      # BUY_ANIMAL
        if m[3] and MARKET_QTY_MODE == "v2":
            m[1] = 1                       # buy it this step, then sell it
    m[5] = 1 if money >= hire_cost(farm.get("hires_today", 0)) else 0
    n_extra = len(farm.get("unlocked_quadrants") or ("NW",)) - 1
    if 0 <= n_extra < len(LAND_PRICES) and money >= LAND_PRICES[n_extra]:
        m[6] = 1                                                  # BUY_LAND
    return m


def market_item_mask(obs, player, mop):
    m = [0] * N_ITEMS
    if mop in (0, 5, 6):                      # NONE / HIRE / BUY_LAND
        m[0] = 1
        return m
    shed, money, _tot = market_shed_upper(obs, player)
    if mop == 1:                              # SELL
        room = SHED_CAPACITY - _tot
        for i, p in enumerate(PRODUCTS):
            if shed.get(p, 0) > 0 or _v2_buy_bonus(obs, p, money, room) > 0:
                m[i] = 1
    elif mop == 2:                            # BUY_SEED
        for i, c in enumerate(CROP_LIST):
            if money >= SEED_COST[c]:
                m[i] = 1
    elif mop == 3:                            # BUY_PRODUCT
        mkt = obs.get("market") or {}
        minv = mkt.get("inventory") or {}
        for p in BUYABLE_PRODUCTS:
            if money >= market_price(p, minv.get(p, MARKET_I0) - 1):
                m[ITEM_IDX[p]] = 1
    elif mop == 4:                            # BUY_ANIMAL
        for a in ANIMAL_LIST:
            if money >= ANIMAL_COST[a]:
                m[ITEM_IDX[a]] = 1
    if not any(m):
        m[0] = 1
    return m


def market_available(mop, item, money, stock_or_price, shed_room, hires,
                     n_extra, order_budget=MAX_MARKET_ORDERS):
    """How many units of this order the seat could actually execute right now.

    `stock_or_price` is the shed count for SELL and the unit price for
    BUY_PRODUCT (whose cost is not a constant); it is ignored otherwise.

    This is the denominator for HALF / ALL and the clip the decoder applies, so
    an order can never be written that the engine would only partially fill.
    Masks stay LOCAL (they ignore the other slots); the decoder's shadow state
    is what keeps a full slate of orders consistent.
    """
    name = ITEMS12[item] if 0 <= item < N_ITEMS else "WHEAT"
    if mop == 1:                                   # SELL
        return max(0, int(stock_or_price))
    if mop == 2:                                   # BUY_SEED
        c = SEED_COST.get(name)
        return int(money // c) if c else 0
    if mop == 3:                                   # BUY_PRODUCT
        if name not in BUYABLE_PRODUCTS:
            return 0
        return min(int(money // max(1, int(stock_or_price))), max(0, shed_room))
    if mop == 4:                                   # BUY_ANIMAL
        c = ANIMAL_COST.get(name)
        if not c:
            return 0
        return min(int(money // c), max(0, shed_room))
    if mop == 5:                                   # HIRE (qty = repeat count)
        n = 0
        spent = 0.0
        while n < order_budget:
            c = hire_cost(hires + n)
            if spent + c > money:
                break
            spent += c
            n += 1
        return n
    if mop == 6:                                   # BUY_LAND (qty = repeat count)
        n = 0
        m2 = money
        k = n_extra
        while k < len(LAND_PRICES) and m2 >= LAND_PRICES[k]:
            m2 -= LAND_PRICES[k]
            k += 1
            n += 1
        return n
    return 0


def _market_state(obs, player):
    farm = obs["farms"][player]
    shed = obs["private"].get("shed") or {}
    money = float(farm.get("money", 0.0))
    room = SHED_CAPACITY - sum(v for v in shed.values() if v > 0)
    hires = farm.get("hires_today", 0)
    n_extra = len(farm.get("unlocked_quadrants") or ("NW",)) - 1
    return shed, money, room, hires, n_extra


def market_qty_mask(obs, player, mop, item):
    m = [0] * N_MKT_QTY
    if mop == 0:
        m[0] = 1
        return m
    farm = obs["farms"][player]
    shed, money, tot = market_shed_upper(obs, player)
    room = SHED_CAPACITY - tot
    hires = farm.get("hires_today", 0)
    n_extra = len(farm.get("unlocked_quadrants") or ("NW",)) - 1
    name = ITEMS12[item] if 0 <= item < N_ITEMS else "WHEAT"
    if mop == 3:                                   # BUY_PRODUCT: price, not stock
        mkt = obs.get("market") or {}
        minv = mkt.get("inventory") or {}
        have_or_price = market_price(name, minv.get(name, MARKET_I0) - 1)
    elif mop == 1:                                 # SELL: stock, + what a
        have_or_price = (shed.get(name, 0)         # same-step buy could add
                         + _v2_buy_bonus(obs, name, money, room))
    else:
        have_or_price = shed.get(name, 0)
    have = market_available(mop, item, money, have_or_price, room, hires, n_extra)
    _fill_qty_mask(m, MARKET_QTY_BINS, have)
    return m


def legal_masks_py(obs, player=None):
    """Stage-1 masks: which units act, where they may point, market slots.

    Returns a dict:
        unit_active [UNITS_MAX]
        target      [UNITS_MAX][N_TILES]
        market_op   [MARKET_SLOTS][N_MKT_OPS]
    The op/item/qty masks are conditional on the choice made above, so they
    come from op_mask_for_tile / item_mask_for / qty_mask_for.
    """
    if player is None:
        player = obs["player"]
    n_units = n_units_of(obs, player)
    tiles = obs["farms"][player]["tiles"]
    quads = set(obs["farms"][player].get("unlocked_quadrants") or ("NW",))
    # A target is worth pointing at if the unit can do anything there: owned
    # tiles, plus the shed-access tiles (shed ops ignore the LOCKED guard).
    tgt = [0] * N_TILES
    for t in range(N_TILES):
        if t in SHED_FLAT or QUAD_OF_TILE[t] in quads:
            tgt[t] = 1
    # a locked, non-shed tile is unreachable as a work site even if its
    # quadrant string says otherwise (defensive; they agree in practice)
    for t in range(N_TILES):
        if tgt[t] and t not in SHED_FLAT and tiles[t // BOARD][t % BOARD] == "LOCKED":
            tgt[t] = 0
    active = [0] * UNITS_MAX
    target = []
    for u in range(UNITS_MAX):
        if u < n_units:
            active[u] = 1
            target.append(list(tgt))
        else:
            row = [0] * N_TILES
            row[0] = 1
            target.append(row)
    mop = _market_op_mask(obs, player)
    return {"unit_active": active, "target": target,
            "market_op": [list(mop) for _ in range(MARKET_SLOTS)]}


# ===========================================================================
#  DECODER
# ===========================================================================
def _step_towards(x, y, tx, ty):
    """First step of a shortest path; x-axis first (movement is unobstructed)."""
    if tx > x:
        return "EAST"
    if tx < x:
        return "WEST"
    if ty > y:
        return "SOUTH"
    return "NORTH"


def nearest_bin(n, have, bins):
    """Recorded quantity -> the bin whose RESOLVED value is closest to it.

    Comparing resolved values (not the raw bin labels) is what makes HALF and
    ALL first-class: with 60 in the shed, "sell 28" is HALF (30), not the
    nearest numeric bin.  Ties prefer ALL, then HALF, then the smallest bin,
    so the label is a deterministic function of (n, have).
    """
    best, bd, brank = 0, None, 9
    for i, b in enumerate(bins):
        v = resolve_qty(i, have, bins)
        d = abs(v - n)
        rank = 0 if b == "ALL" else (1 if b == "HALF" else 2)
        if bd is None or d < bd or (d == bd and rank < brank):
            best, bd, brank = i, d, rank
    return best


def purchase_cost(item, n, inventory):
    """Cash the engine takes for BUY_PRODUCT of `n` units, quoted unit by unit.

    `_commit_unit` quotes at `market_price(item, inventory - 1)` and then
    decrements the inventory, so below I0 each extra unit is dearer than the
    last.  A flat `n * price` estimate overcharges or undercharges and the
    order then clips differently than the shadow state predicted.
    """
    total = 0
    inv = inventory
    for _ in range(int(n)):
        total += market_price(item, inv - 1)
        inv -= 1
    return total


class MarketShadow:
    """The seat's own view of its market slate as it is being written.

    Both `decode_actions_py` (which writes a slate from head indices) and
    `rl2/bc/labels.py` (which reads one back into head indices) drive this
    single object, so a recorded order and its label resolve against exactly
    the same money / shed / price state.  Anything else and HALF / ALL mean two
    different numbers on the two sides, which is a silent labelling error on
    every "sell the shed" turn.

    Order INDEX is preserved: a slot the shadow cannot fill yields no order and
    the caller writes `["PASS"]`.  `_parse_order` ignores that, but
    `_process_market` quotes order i of both players against the same
    pre-commit inventory, so compacting the slate would move every later order
    into a different contest with the opponent.  (Several top teams emit
    exactly this placeholder.)
    """

    __slots__ = ("money", "room", "hires", "n_extra", "avail", "minv", "budget")

    def __init__(self, obs, player, shed_eff, room, budget=MAX_MARKET_ORDERS):
        farm = obs["farms"][player]
        self.money = float(farm.get("money", 0.0))
        self.room = room
        self.hires = farm.get("hires_today", 0)
        self.n_extra = len(farm.get("unlocked_quadrants") or ("NW",)) - 1
        self.avail = dict(shed_eff)
        self.minv = dict((obs.get("market") or {}).get("inventory") or {})
        self.budget = budget

    def available(self, mop, item):
        """Units of this order the seat can actually execute right now."""
        name = ITEMS12[item] if 0 <= item < N_ITEMS else "WHEAT"
        if mop == 1:
            return max(0, self.avail.get(name, 0)) if name in BASE else 0
        if mop == 2:
            c = SEED_COST.get(name)
            return int(self.money // c) if c else 0
        if mop == 3:
            if name not in BUYABLE_PRODUCTS:
                return 0
            inv = self.minv.get(name, MARKET_I0)
            n = 0
            spent = 0
            cap = max(0, self.room)
            while n < cap:
                p = market_price(name, inv - 1 - n)
                if spent + p > self.money:
                    break
                spent += p
                n += 1
            return n
        if mop == 4:
            c = ANIMAL_COST.get(name)
            return min(int(self.money // c), max(0, self.room)) if c else 0
        if mop == 5:
            n = 0
            spent = 0.0
            while n < self.budget:
                c = hire_cost(self.hires + n)
                if spent + c > self.money:
                    break
                spent += c
                n += 1
            return n
        if mop == 6:
            n = 0
            m2 = self.money
            k = self.n_extra
            while k < len(LAND_PRICES) and m2 >= LAND_PRICES[k] and \
                    n < self.budget:
                m2 -= LAND_PRICES[k]
                k += 1
                n += 1
            return n
        return 0

    def order_for(self, mop, item, qty_bin):
        """Resolve one slot, apply its effect, spend the order budget.

        -> the list of engine orders it produced ([] means "not fillable", the
        caller writes the ["PASS"] placeholder).
        """
        if mop == 0 or self.budget <= 0:
            return []
        name = ITEMS12[item] if 0 <= item < N_ITEMS else "WHEAT"
        have = self.available(mop, item)
        n = int(resolve_qty(qty_bin, have, MARKET_QTY_BINS))
        if n <= 0:
            self.budget -= 1
            return []
        if mop == 1:
            inv = self.minv.get(name, MARKET_I0)
            self.money += liquidation_value(name, n, inv)
            self.minv[name] = inv + n
            self.avail[name] = self.avail.get(name, 0) - n
            self.room += n
            out = [["SELL", name, n]]
        elif mop == 2:
            self.money -= n * SEED_COST[name]
            out = [["BUY_SEED", name, n]]
        elif mop == 3:
            inv = self.minv.get(name, MARKET_I0)
            self.money -= purchase_cost(name, n, inv)
            self.minv[name] = inv - n
            self.room -= n
            if MARKET_QTY_MODE == "v2":
                # engine `_commit_unit`: a bought product lands in the shed,
                # so a later slot in the SAME slate can sell it.  v1 never
                # credited this, which is why the expert's opening
                # "BUY_PRODUCT WHEAT 43 / SELL WHEAT 30" pump decoded to the
                # buy alone (see NOTES section 7).
                self.avail[name] = self.avail.get(name, 0) + n
            out = [["BUY_PRODUCT", name, n]]
        elif mop == 4:
            self.money -= n * ANIMAL_COST[name]
            self.room -= n
            if MARKET_QTY_MODE == "v2":
                self.avail[name] = self.avail.get(name, 0) + n
            out = [["BUY_ANIMAL", name, n]]
        elif mop == 5:
            n = min(n, self.budget)
            for k in range(n):
                self.money -= hire_cost(self.hires + k)
            self.hires += n
            out = [["HIRE"]] * n
        elif mop == 6:
            n = min(n, self.budget)
            for _ in range(n):
                self.money -= LAND_PRICES[self.n_extra]
                self.n_extra += 1
            out = [["BUY_LAND"]] * n
        else:
            self.budget -= 1
            return []
        self.budget -= len(out)
        return out

    def bin_for(self, mop, item, n_recorded, bins=MARKET_QTY_BINS):
        """Recorded quantity -> the bin index that reproduces it here."""
        return nearest_bin(n_recorded, self.available(mop, item), bins)


def unit_shed_delta(obs, player, prims):
    """What a slate of unit primitives does to the shed before the market runs.

    -> (shed_eff, room_after).  DROP dumps a whole inventory in insertion
    order, PLACE deposits an item, PICKUP withdraws one; all of them obey
    `shedCapacity` in unit order exactly as `_apply_unit_action` does.
    """
    priv = obs["private"]
    shed = dict(priv.get("shed") or {})
    invs = priv.get("inventories") or [{}]
    room = SHED_CAPACITY - sum(v for v in shed.values() if v > 0)
    for u, p in enumerate(prims):
        if not isinstance(p, (list, tuple)) or not p:
            continue
        name = p[0]
        inv = invs[u] if u < len(invs) else {}
        if name == "DROP":
            for it, n in inv.items():
                if n > 0 and room > 0:
                    take = n if n < room else room
                    shed[it] = shed.get(it, 0) + take
                    room -= take
        elif name == "PLACE" and len(p) >= 3:
            it = p[1]
            try:
                n = int(p[2])
            except (TypeError, ValueError):
                continue
            n = min(n, inv.get(it, 0), max(0, room))
            if n > 0:
                shed[it] = shed.get(it, 0) + n
                room -= n
        elif name == "PICKUP" and len(p) >= 2:
            it = p[1]
            try:
                n = int(p[2]) if len(p) > 2 else 1
            except (TypeError, ValueError):
                n = 1
            n = min(n, shed.get(it, 0))
            if n > 0:
                shed[it] = shed.get(it, 0) - n
                room += n
    return shed, room


def resolve_qty(q_bin, have, bins=QTY_BINS):
    """Bin index + available stock -> the integer quantity to write."""
    q = bins[q_bin] if 0 <= q_bin < len(bins) else 1
    if q == "ALL":
        return have
    if q == "HALF":
        h = have // 2
        return h if h >= 1 else have
    return q if q <= have else have


_resolve_qty = resolve_qty


def decode_actions_py(obs, player, heads):
    """heads -> a kaggriculture action dict.

    heads = {"target","op","item","qty"} (lists indexed by unit) plus
            {"market_op","market_item","market_qty"} (lists of MARKET_SLOTS).

    Rules implemented here, all of them load-bearing:

      * not standing on the target -> emit the path step instead of the op;
      * PLANT is capped per crop at the seeds actually in stock, because the
        engine drops ALL PLANT requests for a crop whose demand exceeds
        supply (`interpreter`'s `blocked` set) -- one greedy unit would
        otherwise cancel every other planting that turn;
      * SELL orders are emitted before every other order type;
      * qty ALL for a SELL counts the shed PLUS what this turn's DROP /
        PLACE_SHED will add, because unit actions resolve before the market;
      * at most MAX_MARKET_ORDERS orders survive.
    """
    farm = obs["farms"][player]
    priv = obs["private"]
    shed = dict(priv.get("shed") or {})
    seeds = dict(priv.get("seeds") or {})
    invs = priv.get("inventories") or [{}]
    pos = unit_positions(obs, player)
    n_units = len(pos)

    tgt = heads["target"]
    ops = heads["op"]
    items = heads["item"]
    qtys = heads["qty"]

    prim = []
    seed_left = dict(seeds)
    room = SHED_CAPACITY - sum(v for v in shed.values() if v > 0)
    pending = {}                       # what lands in the shed before the market
    for u in range(n_units):
        x, y = pos[u]
        t = tgt[u]
        tx, ty = t % BOARD, t // BOARD
        if (tx, ty) != (x, y):
            prim.append([_step_towards(x, y, tx, ty)])
            continue
        op = ops[u]
        name = OP_PRIMITIVE[op]
        inv = invs[u] if u < len(invs) else {}
        if op == 0:
            prim.append(["PASS"])
        elif op == 1:                                     # PLANT
            crop = ITEMS12[items[u]]
            if crop in CROP_IDX and seed_left.get(crop, 0) > 0:
                seed_left[crop] -= 1
                prim.append(["PLANT", crop])
            else:
                prim.append(["PASS"])
        elif op in (3, 4, 2, 6, 7, 8, 10, 11):            # no item, no qty
            prim.append([name])
        elif op == 5:
            prim.append(["FERTILIZE"])
        elif op == 9:
            prim.append(["FEED"])
        elif op == 12:                                    # DROP: whole inventory
            prim.append(["DROP"])
            for it, n in inv.items():
                if n > 0 and room > 0:
                    take = n if n < room else room
                    pending[it] = pending.get(it, 0) + take
                    room -= take
        elif op == 13:                                    # PICKUP item/qty
            it = ITEMS12[items[u]]
            n = _resolve_qty(qtys[u], shed.get(it, 0))
            if n > 0:
                prim.append(["PICKUP", it, n])
                shed[it] = shed.get(it, 0) - n
                room += n
            else:
                prim.append(["PASS"])
        elif op == 14 or op == 15:                        # PLACE animal
            it = ITEMS12[items[u]]
            if inv.get(it, 0) > 0:
                prim.append(["PLACE", it])
            else:
                prim.append(["PASS"])
        elif op == 16:                                    # PLACE into the shed
            it = ITEMS12[items[u]]
            n = _resolve_qty(qtys[u], inv.get(it, 0))
            if n > 0 and room > 0:
                take = n if n < room else room
                prim.append(["PLACE", it, take])
                pending[it] = pending.get(it, 0) + take
                room -= take
            else:
                prim.append(["PASS"])
        else:
            prim.append(["PASS"])

    while len(prim) < n_units:
        prim.append(["PASS"])
    farmer = prim[0] if prim else ["PASS"]
    hands = prim[1:]
    # units past UNITS_MAX are never commanded; the engine reads a short list
    # as "the rest PASS"
    n_real_hands = len(farm.get("hands") or ())
    if len(hands) < n_real_hands:
        hands = hands + [["PASS"]] * (n_real_hands - len(hands))

    # ------------------------------------------------------------- market
    shed_eff = dict(shed)
    for it, n in pending.items():
        shed_eff[it] = shed_eff.get(it, 0) + n
    sh = MarketShadow(obs, player, shed_eff, room)
    # Pass A = SELL, pass B = everything else.  A slot the shadow cannot fill
    # emits `["PASS"]` instead of being dropped (see MarketShadow).
    if MARKET_QTY_MODE == "v2":
        # Slot index IS the engine's order index: the slate is emitted in slot
        # order so a buy can fund a sell and a sell can fund a buy exactly as
        # the author (expert or policy) sequenced it.  `labels.classify_market`
        # writes slots in the same order, so the round trip is faithful.
        orders = []
        for s in range(MARKET_SLOTS):
            if sh.budget <= 0:
                break
            mop = heads["market_op"][s]
            if mop == 0:
                continue
            got = sh.order_for(mop, heads["market_item"][s],
                               heads["market_qty"][s])
            orders.extend(got or [["PASS"]])
        market = orders[:MAX_MARKET_ORDERS]
        return {"farmer": farmer, "hands": hands, "market": market}

    sells, others = [], []
    for want in (1, 0):
        for s in range(MARKET_SLOTS):
            if sh.budget <= 0:
                break
            mop = heads["market_op"][s]
            if mop == 0 or (mop == 1) != bool(want):
                continue
            got = sh.order_for(mop, heads["market_item"][s],
                               heads["market_qty"][s])
            (sells if want else others).extend(got or [["PASS"]])

    market = (sells + others)[:MAX_MARKET_ORDERS]
    return {"farmer": farmer, "hands": hands, "market": market}


