# NORMATIVE END
# ===========================================================================
#
# Everything below this line is OUTSIDE the hashed contract.  `SPEC_HASH`
# covers the encoding and the action vocabulary; `TargetMemory` changes
# neither, so adding it does not invalidate `native/src/encode.rs`.  It IS
# part of the policy though, so W1 must mirror it in VecEnv before PPO runs
# with it enabled -- until then it is opt-in and off by default, and a VecEnv
# without it matches a decoder without it exactly.


class TargetMemory:
    """Inference-time sticky targets: commit to a tile until you get there.

    The deployed BC policy re-picks `target` from scratch every step, and it is
    only ~66% accurate on the steps where the expert was walking.  A unit that
    picks tile A, steps toward it, then picks tile B and steps back, never
    arrives and never acts: measured on the deployed agent, 78% of unit-steps
    are PASS against 7% in the data.  Committing removes the per-step coin flip
    without changing a single weight.

    THE RULE (mirror this exactly, W1):

      * memory is cleared whenever `hour == 0` -- `_end_of_day` teleports every
        unit to the shed and drops the hands, so unit index `u` is a different
        worker the next morning, and nothing may carry across;
      * a unit with no remembered target takes the head's argmax, and remembers
        it only if it is not the tile it is already standing on;
      * a unit standing ON its remembered target keeps it for this step (so the
        op is chosen there) and then forgets it, so the next step re-decides;
      * a unit whose remembered target no longer admits any op but PASS
        (`op_mask_for_tile` is all zero except index 0) forgets it and
        re-decides -- someone else watered that plant, the animal was fed, the
        tile was dug;
      * otherwise the remembered target is kept and the decoder emits the next
        path step.

    op / item / qty are ALWAYS chosen fresh from the current logits at whatever
    target survives this rule; only the pointer head is sticky.
    """

    __slots__ = ("tgt", "day", "hour")

    def __init__(self):
        self.tgt = {}
        self.day = -1
        self.hour = -1

    def begin_step(self, obs):
        day = obs.get("day", 0)
        hour = obs.get("hour", 0)
        if hour == 0 or day != self.day:
            self.tgt.clear()
        self.day = day
        self.hour = hour

    def choose(self, obs, player, u, fresh, pos):
        """-> the target tile to use for unit `u` this step."""
        cur = pos[1] * BOARD + pos[0]
        t = self.tgt.get(u)
        if t is not None:
            if t == cur:
                del self.tgt[u]                  # arrived: act, then re-decide
                return t
            m = op_mask_for_tile(obs, player, u, t)
            for i in range(1, N_OPS):
                if m[i]:
                    return t                     # still something to do there
            del self.tgt[u]
        if fresh != cur:
            self.tgt[u] = fresh
        return fresh


def working_targets(obs, player, n_units, positions, target_mask):
    """Precompute, per tile, which ops each unit could do there.

    Returns `(tile_bits, unit_bits)` where bit *i* of an entry is op *i*'s
    legality.  `op_mask_for_tile(u, t)` is `tile_bits[t] & unit_bits[u]` (the
    factorization the op table was designed around), so "is there anything for
    unit u to do on tile t" is one AND and a compare instead of 1,600 mask
    builds per step.
    """
    tile_bits = [0] * N_TILES
    for t in range(N_TILES):
        if not target_mask[t]:
            continue
        m = tile_caps(obs, player, t)
        b = 0
        for i in range(N_OPS):
            if m[i]:
                b |= 1 << i
        tile_bits[t] = b
    unit_bits = []
    for u in range(n_units):
        m = unit_caps(obs, player, u)
        b = 0
        for i in range(N_OPS):
            if m[i]:
                b |= 1 << i
        unit_bits.append(b)
    return tile_bits, unit_bits


NOT_PASS = ~1


def pick_working_target(t, cur, op_logits, target_logits, target_mask,
                        tile_bits, unit_bit):
    """"No idle stay": never stand still with nothing to do.

    If the chosen target is the tile the unit is already on AND the op it would
    take there is PASS, walk somewhere useful instead: the highest-target-logit
    tile `t' != cur` whose best LEGAL op for this unit is not PASS.  If no such
    tile exists the unit genuinely has nothing to do and `t` is kept.

    "Best legal op" is the argmax of the op head restricted to that tile's
    mask -- the same quantity the decoder would compute there -- so this only
    ever swaps a target the policy was going to waste.  Measured cause: 96% of
    the deployed agent's acting steps are PASS and 60% of those are on tiles
    where PASS is the only legal op (`rl2/diag_target.py`).

    Post-NORMATIVE and opt-in, exactly like `TargetMemory`: it changes no
    encoding, so it does not move `SPEC_HASH`, but W1 must mirror it in VecEnv
    before PPO runs with it enabled.
    """
    if t != cur:
        return t
    order = sorted(range(N_OPS), key=lambda i: -op_logits[i])
    if _best_legal_op(order, tile_bits[cur] & unit_bit) != OP_PASS:
        return t
    best, bv = -1, None
    for tt in range(N_TILES):
        if tt == cur or not target_mask[tt]:
            continue
        bits = tile_bits[tt] & unit_bit
        if not (bits & NOT_PASS):
            continue
        if _best_legal_op(order, bits) == OP_PASS:
            continue
        v = target_logits[tt]
        if best < 0 or v > bv:
            best, bv = tt, v
    return best if best >= 0 else t


def _best_legal_op(order, bits):
    for i in order:
        if bits >> i & 1:
            return i
    return OP_PASS


# ---------------------------------------------------------------------------
# Autoregressive target claiming
# ---------------------------------------------------------------------------
# The policy scores every unit's target from a shared trunk and then takes each
# argmax INDEPENDENTLY, so units routinely converge on the same tile.  Nothing
# arbitrates: whoever acts first waters the plant and the rest arrive to a tile
# whose op is now a no-op.  `v4`, the expert these labels come from, never does
# this -- it assigns tiles globally (angular wedges -> nearest-neighbour tours
# -> unit-to-wedge matching), so "two units, one tile" is a pure artifact of
# our factorisation, not of the data.
#
# THE RULE (mirror this exactly, W1):
#
#   * units are decoded in sequence, not in parallel.  Two orders are
#     supported: "index" (farmer, then hands in index order) and "conf"
#     (descending max target logit, so the most certain unit picks first);
#   * a tile chosen by an earlier unit this step is removed from the target
#     mask of every later unit;
#   * EXCEPT the four shed-access tiles, which are never claimed: DROP, PICKUP
#     and PLACE_SHED all act on the shed rather than on the tile, so any number
#     of units can work there in the same step without interfering.  Every
#     other op mutates the tile it stands on (WATER sets watered_today, HARVEST
#     zeroes yield_units, FEED/CARE set their flag, PLANT/BUILD/DIG replace the
#     tile outright), so a second unit's identical op is a guaranteed no-op;
#   * a unit's remembered sticky target keeps its claim: all remembered targets
#     are claimed BEFORE the sequence runs, and a unit may always take a tile
#     it already owns;
#   * if claiming leaves a unit no legal target at all, the claim mask is
#     ignored for that unit (a forced collision beats an illegal action).
#
# Post-NORMATIVE and opt-in, like TargetMemory and pick_working_target: no
# encoding changes, so SPEC_HASH does not move.
AR_ORDERS = ("index", "conf")


class ClaimSet:
    """Tiles spoken for by earlier units in this step's decode sequence."""

    __slots__ = ("owner",)

    def __init__(self):
        self.owner = {}

    def reset(self):
        self.owner.clear()

    def free_for(self, u, t):
        """May unit `u` target tile `t`?"""
        if t in SHED_FLAT:
            return True
        o = self.owner.get(t)
        return o is None or o == u

    def claim(self, u, t):
        if t not in SHED_FLAT:
            self.owner[t] = u

    def mask_for(self, u, target_mask):
        """`target_mask` with tiles owned by other units removed.

        Returns the original row when claiming would leave nothing legal --
        an illegal target is worse than a shared one.
        """
        out = [m if (m and self.free_for(u, t)) else 0
               for t, m in enumerate(target_mask)]
        return out if any(out) else target_mask


# ---------------------------------------------------------------------------
# Autopsy guards (opt-in, post-NORMATIVE)
# ---------------------------------------------------------------------------
# Six of forty-eight games against `starter` end near $0, and all six fail the
# same way: seeds are bought, tiles are planted, hands are hired -- and then
# 8-18 tiles weed over, the shed peaks at 5-32 of 100, and the herd never gets
# past three animals.  The policy spends itself to zero while its farm dies.
# These three guards are decode-level and cheap; each one is a direct answer to
# one of those counts.
GUARD_THIRSTY_PER_UNIT = 3.0   # thirsty crop tiles one unit can service a day
GUARD_FEED_RESERVE = 60.0      # cash held back per placed animal
GUARD_HERD_FLOOR = 8           # animals below which seed buying yields to stock


def farm_pressure(obs, player):
    """(thirsty crop tiles, placed animals) -- the two guard inputs."""
    tiles = obs["farms"][player]["tiles"]
    day = obs.get("day", 0)
    thirsty = animals = 0
    for row in tiles:
        for t in row:
            if not isinstance(t, dict):
                continue
            k = t.get("kind")
            if k == "PLANT":
                if not t.get("watered_today"):
                    thirsty += 1
            elif t.get("animal") is not None:
                animals += 1
    return thirsty, animals


def guard_unit_op(op, obs, player, n_units, thirsty):
    """Plant throttle: a seed planted past watering capacity is negative value.

    Two dry days turn a tile into a weed, so planting while the farm already
    has more thirsty tiles than the crew can water spends cash to create a
    weed.  Returns the op to use (PASS instead of PLANT when over capacity).
    """
    if op == OP_IDX["PLANT"] and thirsty > GUARD_THIRSTY_PER_UNIT * max(1, n_units):
        return OP_PASS
    return op


def guard_market_op(mop, obs, player, animals, money):
    """Cash reserve + herd floor.

    * HIRE and BUY_SEED are refused below `GUARD_FEED_RESERVE` per placed
      animal -- the tail games hire and sow themselves to zero while the
      animals they already own starve;
    * BUY_SEED yields to BUY_ANIMAL while the herd is under `GUARD_HERD_FLOOR`;
      animals are the reliable income and the tail games never build one.
    """
    if mop in (2, 5) and money < GUARD_FEED_RESERVE * animals:
        return 0
    return mop


# The herd floor as first written ("refuse BUY_SEED until 8 animals") was a
# 100x regression: a guard can only REMOVE an option, it cannot make the policy
# pick BUY_ANIMAL instead, so the agent simply stopped farming and never bought
# the animals either.  Measured: median vs the tape 16,318 -> 1,586.  Kept here
# as a named constant and a warning rather than deleted, because the failure
# mode it was aimed at (peak herd of exactly 3 in every zero-tail game) is real
# and needs a POLICY fix, not a mask.
GUARD_HERD_FLOOR_DISABLED = GUARD_HERD_FLOOR


def decode_order(n_units, target_logits, mode="index"):
    """The sequence units are decoded in: `AR_ORDERS`."""
    if mode == "conf" and target_logits is not None:
        return sorted(range(n_units), key=lambda u: -max(target_logits[u]))
    return list(range(n_units))



SPEC_TABLES = {
    "board": BOARD, "units_max": UNITS_MAX, "grid_c": GRID_C,
    "unit_f": UNIT_F_N, "glob_n": GLOB_N,
    "grid_ch": GRID_CH, "unit_ch": UNIT_F,
    "glob_f": [list(x) for x in GLOB_F],
    "ops": list(OPS), "op_primitive": list(OP_PRIMITIVE),
    "op_item_kind": list(OP_ITEM_KIND), "op_uses_qty": list(OP_USES_QTY),
    "items12": list(ITEMS12), "qty_bins": [str(q) for q in QTY_BINS],
    "market_slots": MARKET_SLOTS, "market_ops": list(MARKET_OPS),
    "market_qty_bins": [str(q) for q in MARKET_QTY_BINS],
    "crop_sched": {k: list(v) for k, v in CROP_SCHED.items()},
    "animal_sched": {k: list(v) for k, v in ANIMAL_SCHED.items()},
    "market_params": {k: list(v) for k, v in MARKET_PARAMS.items()},
    "base": BASE, "t_anchor": T_ANCHOR, "hinge_gain": HINGE_GAIN,
    "shops": {k: list(v) for k, v in SHOPS.items()},
    "seed_cost": SEED_COST, "animal_cost": ANIMAL_COST,
    "land_prices": list(LAND_PRICES), "shed_capacity": SHED_CAPACITY,
    "max_market_orders": MAX_MARKET_ORDERS, "market_i0": MARKET_I0,
    # version 2: an EMPTY structure writes the animal one-hot of the species it
    #   accepts.
    # version 3 (2026-09-12): market masks are computed on an UPPER BOUND of
    #   the shed and cash this step (`market_shed_upper`) rather than on the
    #   pre-action state -- the engine drops before the market and commits
    #   orders sequentially, so sell-what-you-drop and buy-with-what-you-sold
    #   are legal and were being masked out.
    # SPEC_HASH covers SPEC_TABLES, not function bodies, so a behavioural
    # change needs this bump to be visible to native/src/encode.rs.
    "version": 3,
}
SPEC_HASH = hashlib.sha256(
    json.dumps(SPEC_TABLES, sort_keys=True, separators=(",", ":")).encode()
).hexdigest()

# Head layout consumed by rl2/net.py and rl2/export.py.  (name, n)
UNIT_HEADS = (("target", N_TILES), ("op", N_OPS), ("item", N_ITEMS), ("qty", N_QTY))
MARKET_HEADS = (("market_op", N_MKT_OPS), ("market_item", N_ITEMS),
                ("market_qty", N_MKT_QTY))


def spec_summary():
    return {
        "SPEC_HASH": SPEC_HASH,
        "grid": [N_TILES, GRID_C],
        "units": [UNITS_MAX, UNIT_F_N],
        "glob": GLOB_N,
        "unit_heads": {n: k for n, k in UNIT_HEADS},
        "market": {"slots": MARKET_SLOTS,
                   "per_slot": {n: k for n, k in MARKET_HEADS},
                   "logits": MARKET_LOGITS},
    }


if __name__ == "__main__":
    print(json.dumps(spec_summary(), indent=2))
    print("ops:")
    for i, o in enumerate(OPS):
        print(f"  {i:2d} {o:20s} prim={OP_PRIMITIVE[i]:18s} "
              f"item={OP_ITEM_KIND[i]:8s} qty={int(OP_USES_QTY[i])}")

