class _NS(object):
    """`rl2/market_cand.py` says `from rl2 import spec as S`; there is no
    package here, so the already-exec'd spec namespace is handed to it as an
    object with the same attributes."""

    def __init__(self, d):
        self.__dict__.update(d)


