_N_MKT_OPS = _SPEC["N_MKT_OPS"]
_N_ITEMS = _SPEC["N_ITEMS"]
_N_MKT_QTY = _SPEC["N_MKT_QTY"]
_PASS = {"farmer": ["PASS"], "hands": [], "market": []}

_D = 96
_LAYERS = 2
_HEADS = 4
_DH = _D // _HEADS
_PTR = 64
_TOPK = 48
_SHAPES = [('te_cols', [26, 96]), ('tile_b0', [96]), ('pos_emb', [100, 96]), ('unit_w', [96, 26]), ('unit_b', [96]), ('glob_w', [96, 96]), ('glob_b', [96]), ('mkt_w', [96, 96]), ('mkt_b', [96]), ('slot_emb', [10, 96]), ('l0_Wq', [96, 96]), ('l0_bq', [96]), ('l0_Wk', [96, 96]), ('l0_bk', [96]), ('l0_Wv', [96, 96]), ('l0_bv', [96]), ('l0_Wo', [96, 96]), ('l0_bo', [96]), ('l0_W1', [384, 96]), ('l0_b1', [384]), ('l0_W2', [96, 384]), ('l0_b2', [96]), ('l0_n1w', [96]), ('l0_n1b', [96]), ('l0_n2w', [96]), ('l0_n2b', [96]), ('l1_Wq', [96, 96]), ('l1_bq', [96]), ('l1_Wk', [96, 96]), ('l1_bk', [96]), ('l1_Wv', [96, 96]), ('l1_bv', [96]), ('l1_Wo', [96, 96]), ('l1_bo', [96]), ('l1_W1', [384, 96]), ('l1_b1', [384]), ('l1_W2', [96, 384]), ('l1_b2', [96]), ('l1_n1w', [96]), ('l1_n1b', [96]), ('l1_n2w', [96]), ('l1_n2b', [96]), ('norm_w', [96]), ('norm_b', [96]), ('qw', [64, 96]), ('qb', [64]), ('ptrw', [64, 96]), ('snw', [96]), ('snb', [96]), ('sptrw', [64, 96]), ('opw', [17, 96]), ('opb', [17]), ('itw', [12, 96]), ('itb', [12]), ('qtw', [15, 96]), ('qtb', [15]), ('mopw', [7, 96]), ('mopb', [7]), ('mitw', [12, 96]), ('mitb', [12]), ('mqtw', [34, 96]), ('mqtb', [34])]
_CAND_SCALE = 1.0 / _math.sqrt(_D)
# Subtracted from the STOP candidate's score (candidate 0) before the argmax.
# The AR loop labels STOP on every decision step -- it terminates every slate
# and it is the ONLY label on the ~55% of steps with no order -- so STOP holds
# roughly half the AR label mass while each order token holds under 2%.  Under
# argmax that prior wins and the agent stops trading: measured 11,872 median
# money vs the public tape at 0, 61,355 at 2, 63,193 at 5, 2,717 at 8 (12 games
# each, notebooks/market_cand.md section G3b).  A scalar here is a decode rule
# like sticky / no-idle / temperature; the principled fix is to re-weight the
# STOP label in `cand_market_loss`.
_STOP_BIAS = 0.0


_W_FORMATS = {'te_cols': 'e', 'tile_b0': 'f', 'pos_emb': 'f', 'unit_w': 'e', 'unit_b': 'f', 'glob_w': 'e', 'glob_b': 'f', 'mkt_w': 'e', 'mkt_b': 'f', 'slot_emb': 'f', 'l0_Wq': 'e', 'l0_bq': 'f', 'l0_Wk': 'e', 'l0_bk': 'f', 'l0_Wv': 'e', 'l0_bv': 'f', 'l0_Wo': 'e', 'l0_bo': 'f', 'l0_W1': 'e', 'l0_b1': 'f', 'l0_W2': 'e', 'l0_b2': 'f', 'l0_n1w': 'f', 'l0_n1b': 'f', 'l0_n2w': 'f', 'l0_n2b': 'f', 'l1_Wq': 'e', 'l1_bq': 'f', 'l1_Wk': 'e', 'l1_bk': 'f', 'l1_Wv': 'e', 'l1_bv': 'f', 'l1_Wo': 'e', 'l1_bo': 'f', 'l1_W1': 'e', 'l1_b1': 'f', 'l1_W2': 'e', 'l1_b2': 'f', 'l1_n1w': 'f', 'l1_n1b': 'f', 'l1_n2w': 'f', 'l1_n2b': 'f', 'norm_w': 'f', 'norm_b': 'f', 'qw': 'e', 'qb': 'f', 'ptrw': 'e', 'snw': 'f', 'snb': 'f', 'sptrw': 'e', 'opw': 'e', 'opb': 'f', 'itw': 'e', 'itb': 'f', 'qtw': 'e', 'qtb': 'f', 'mopw': 'f', 'mopb': 'f', 'mitw': 'e', 'mitb': 'f', 'mqtw': 'e', 'mqtb': 'f'}

def _unpack(blob):
    raw = _lzma.decompress(_b64.b85decode(blob))
    out = {}
    offset = 0
    for name, shape in _SHAPES:
        fmt = _W_FORMATS[name]
        n = shape[0] if len(shape) == 1 else shape[0] * shape[1]
        flat = _struct.unpack_from("<%d%s" % (n, fmt), raw, offset)
        offset += n * _struct.calcsize(fmt)
        out[name] = list(flat) if len(shape) == 1 else [list(flat[k*shape[1]:(k+1)*shape[1]]) for k in range(shape[0])]
    if offset != len(raw):
        raise RuntimeError("weight blob length mismatch")
    return out


_P = _unpack(_BLOB)
_LAYER_W = [{k: _P[f"l{l}_{k}"] for k in (
    "Wq", "bq", "Wk", "bk", "Wv", "bv", "Wo", "bo",
    "W1", "b1", "W2", "b2", "n1w", "n1b", "n2w", "n2b")}
    for l in range(_LAYERS)]
_SQRT2INV = 1.0 / _math.sqrt(2.0)
_PTR_SCALE = 1.0 / _math.sqrt(_PTR)


def _lin(W, b, x):
    return [bb + sum(map(_mul, row, x)) for row, bb in zip(W, b)]


def _layernorm(x, w, b, eps=1e-5):
    n = len(x)
    m = sum(x) / n
    var = sum((v - m) * (v - m) for v in x) / n
    inv = 1.0 / _math.sqrt(var + eps)
    return [(v - m) * inv * wi + bi for v, wi, bi in zip(x, w, b)]


def _gelu(v):
    return [0.5 * x * (1.0 + _math.erf(x * _SQRT2INV)) for x in v]


def _add(a, b):
    return [x + y for x, y in zip(a, b)]


def _tiles(grid):
    """tile_in(grid) + pos_emb + (tile_in.bias + type_emb[0]), skipping the
    zeros -- a tile row is ~7 of 26 channels nonzero (same trick as
    rl2/export.py's `_tiles`, bit-identical to the dense matmul)."""
    te = _P["te_cols"]
    b0 = _P["tile_b0"]
    pe = _P["pos_emb"]
    out = []
    rng = range(_GRID_C)
    for t in range(_N_TILES):
        g = grid[t]
        p = pe[t]
        acc = [p[k] + b0[k] for k in range(_D)]
        for j in rng:
            v = g[j]
            if v:
                col = te[j]
                acc = [a + v * c for a, c in zip(acc, col)]
        out.append(acc)
    return out


def _mha(toks, L):
    T = len(toks)
    Q = [_lin(L["Wq"], L["bq"], t) for t in toks]
    K = [_lin(L["Wk"], L["bk"], t) for t in toks]
    V = [_lin(L["Wv"], L["bv"], t) for t in toks]
    scale = 1.0 / _math.sqrt(_DH)
    out = [[0.0] * _D for _ in range(T)]
    for h in range(_HEADS):
        s = h * _DH
        e = s + _DH
        Qh = [q[s:e] for q in Q]
        Kh = [k[s:e] for k in K]
        Vcols = list(zip(*[v[s:e] for v in V]))
        for i in range(T):
            qi = Qh[i]
            scores = [sum(map(_mul, qi, Kh[j])) * scale for j in range(T)]
            mx = max(scores)
            exps = [_math.exp(sc - mx) for sc in scores]
            tot = sum(exps)
            wts = [ev / tot for ev in exps]
            out[i][s:e] = [sum(map(_mul, wts, col)) for col in Vcols]
    return [_lin(L["Wo"], L["bo"], o) for o in out]


def _encoder_layer(toks, L):
    normed = [_layernorm(t, L["n1w"], L["n1b"]) for t in toks]
    attn = _mha(normed, L)
    toks = [_add(t, a) for t, a in zip(toks, attn)]
    normed2 = [_layernorm(t, L["n2w"], L["n2b"]) for t in toks]
    ff = [_lin(L["W2"], L["b2"], _gelu(_lin(L["W1"], L["b1"], t)))
          for t in normed2]
    return [_add(t, f) for t, f in zip(toks, ff)]


def _select_tiles(grid):
    """The K highest-priority tiles, ascending -- rl2/net_tf.select_tiles.

    Every term is a small integer in float, and `* 256 - t` makes the scores
    distinct, so this picks exactly the set torch.topk picks; no tie to break.
    """
    sc = []
    for t in range(_N_TILES):
        g = grid[t]
        p = 100.0 if g[24] > 0.0 else 0.0
        p += g[23] * 90.0
        p += (g[2] + g[3] + g[4] + g[5]) * 60.0
        p += g[0] * 25.0
        sc.append(p * 256.0 - t)
    sel = sorted(range(_N_TILES), key=lambda t: -sc[t])[:_TOPK]
    sel.sort()
    return sel


def _logits(grid, units, glob, unit_tile, n):
    tiles = _tiles(grid)
    unit_toks = []
    for u in range(n):
        ut = unit_tile[u]
        x = _lin(_P["unit_w"], _P["unit_b"], units[u])
        x = _add(x, _P["pos_emb"][ut])
        x = _add(x, tiles[ut])
        unit_toks.append(x)
    glob_tok = _lin(_P["glob_w"], _P["glob_b"], glob)
    mkt_base = _lin(_P["mkt_w"], _P["mkt_b"], glob)
    slot = _P["slot_emb"]
    mkt_toks = [[mkt_base[k] + slot[j][k] for k in range(_D)]
                for j in range(_MARKET_SLOTS)]

    if _TOPK:
        sel = _select_tiles(grid)
        tile_toks = [tiles[t] for t in sel]
    else:
        sel = None
        tile_toks = tiles

    toks = tile_toks + unit_toks + [glob_tok] + mkt_toks
    for L in _LAYER_W:
        toks = _encoder_layer(toks, L)
    toks = [_layernorm(t, _P["norm_w"], _P["norm_b"]) for t in toks]

    nk = len(tile_toks)
    tile_h = toks[:nk]
    unit_h = toks[nk:nk + n]
    mkt_h = toks[nk + n + 1:]

    ptrw = _P["ptrw"]
    zero = [0.0] * _PTR
    if sel is None:
        keys = [_lin(ptrw, zero, th) for th in tile_h]
    else:
        # kept tiles get a contextual key; the pruned ones get a static key
        # off their own input embedding (rl2/net_tf.py: ptr_static/key_norm),
        # so the pointer head still ranges over all 100 tiles
        keys = [None] * _N_TILES
        for i, t in enumerate(sel):
            keys[t] = _lin(ptrw, zero, tile_h[i])
        sptrw, snw, snb = _P["sptrw"], _P["snw"], _P["snb"]
        for t in range(_N_TILES):
            if keys[t] is None:
                keys[t] = _lin(sptrw, zero, _layernorm(tiles[t], snw, snb))
    tgt, op, item, qty = [], [], [], []
    for uh in unit_h:
        qv = _lin(_P["qw"], _P["qb"], uh)
        tgt.append([sum(map(_mul, qv, k)) * _PTR_SCALE for k in keys])
        op.append(_lin(_P["opw"], _P["opb"], uh))
        item.append(_lin(_P["itw"], _P["itb"], uh))
        qty.append(_lin(_P["qtw"], _P["qtb"], uh))
    if _MARKET_HEAD == "cand":
        # slot 0's token is the market context; the candidate tokens are scored
        # against it one AR step at a time (see _market_cand_slate)
        return {"target": tgt, "op": op, "item": item, "qty": qty,
                "mkt_ctx": mkt_h[0]}
    mop, mitem, mqty = [], [], []
    for mh in mkt_h:
        mop.append(_lin(_P["mopw"], _P["mopb"], mh))
        mitem.append(_lin(_P["mitw"], _P["mitb"], mh))
        mqty.append(_lin(_P["mqtw"], _P["mqtb"], mh))
    return {"target": tgt, "op": op, "item": item, "qty": qty,
            "market_op": mop, "market_item": mitem, "market_qty": mqty}


def _cand_scores(ctx, state, embs):
    """Pointer scores over the candidate embeddings (rl2/net_tf.cand_logits)."""
    q = _lin(_P["cqw"], _P["cqb"], [ctx[k] + state[k] for k in range(_D)])
    bw = _P["cbw"][0]
    bb = _P["cbb"][0]
    sc = []
    for e in embs:
        sc.append(sum(map(_mul, q, e)) * _CAND_SCALE
                  + sum(map(_mul, bw, e)) + bb)
    if sc and _STOP_BIAS:
        sc[0] = sc[0] - _STOP_BIAS          # candidate 0 is always STOP
    return sc


def _market_cand_slate(obs, player, ctx, prims):
    """The AR market loop -> per-slot (op, item, qty_bin).

    `prims` are THIS step's decoded unit primitives, so the shadow the loop
    drives is the one `decode_actions_py` will rebuild when it reaches the
    market (rl2/market_cand.py's contract; proved against the Rust port by
    `rl2/difftest.py --market-cand`).
    """
    sh = _cand_shadow.from_obs(obs, player, prims)
    state = [0.0] * _D
    slate = []
    cinw, cinb, cprevw = _P["cinw"], _P["cinb"], _P["cprevw"]
    for _t in range(_AR_MAX):
        cands = _cand_enum(sh)
        embs = [_gelu(_lin(cinw, cinb, c[5])) for c in cands]
        sc = _cand_scores(ctx, state, embs)
        # every candidate is legal by construction, so the mask is all-ones --
        # that IS the point of the design
        i = _choose(sc, [1] * len(sc))
        if not _cand_pick(sh, cands, i):
            break
        slate.append((cands[i][0], cands[i][1], cands[i][2]))
        e = embs[i]
        upd = [sum(map(_mul, row, e)) for row in cprevw]
        state = [state[k] + upd[k] for k in range(_D)]
    while len(slate) < _MARKET_SLOTS:
        slate.append((0, 0, 0))
    return slate


def _choose(logits, mask):
    """Masked categorical sample at `_TEMP`, or the argmax when _SAMPLE is off
    (see rl2/export.py's `_choose` -- identical rule, copied verbatim)."""
    if not _SAMPLE:
        return _argmax(logits, mask)
    best = -1
    mx = 0.0
    n = 0
    for i, m in enumerate(mask):
        if m:
            v = logits[i] / _TEMP
            if best < 0 or v > mx:
                mx = v
                best = i
            n += 1
    if best < 0:
        return 0
    if n == 1:
        return best
    tot = 0.0
    ws = []
    for i, m in enumerate(mask):
        if m:
            w = _math.exp(logits[i] / _TEMP - mx)
            tot += w
            ws.append((i, tot))
    r = _RNG.random() * tot
    for i, c in ws:
        if r <= c:
            return i
    return ws[-1][0]


def _argmax(logits, mask):
    best = -1
    bv = 0.0
    for i, m in enumerate(mask):
        if m:
            v = logits[i]
            if best < 0 or v > bv:
                best = i
                bv = v
    return best if best >= 0 else 0


_STATS = {"calls": 0, "fails": 0, "last_error": None, "ms": 0.0}
_STRICT = bool(_os.environ.get("KAGG_RL2_STRICT"))


def _play(obs):
    player = obs["player"]
    if _SAMPLE and _SPEC["step_of"](obs) == 0:
        _RNG.seed(_SEED)
    grid, units, glob = _encode(obs, player)
    masks = _legal(obs, player)
    n = _n_units_of(obs, player)
    pos = _unit_positions(obs, player)
    unit_tile = []
    for u in range(n):
        r = units[u]
        unit_tile.append(int(round(r[1] * 10.0)) * 10 + int(round(r[0] * 10.0)))
    lg = _logits(grid, units, glob, unit_tile, n)
    if _STICKY:
        _MEM.begin_step(obs)
    tile_bits = unit_bits = None
    if _NOIDLE:
        tile_bits, unit_bits = _working_targets(obs, player, n, pos,
                                                masks["target"][0])
    heads = {"target": [0] * n, "op": [0] * n, "item": [0] * n, "qty": [0] * n,
             "market_op": [], "market_item": [], "market_qty": []}
    if _AR:
        _CLAIMS.reset()
        if _STICKY:
            for u in range(n):
                t0 = _MEM.tgt.get(u)
                if t0 is not None:
                    _CLAIMS.claim(u, t0)
    thirsty = animals = 0
    if _GUARDS:
        thirsty, animals = _farm_pressure(obs, player)
    seen_t = {}
    for u in _decode_order(n, lg["target"], _AR or "index"):
        tmask = masks["target"][u]
        if _AR:
            tmask = _CLAIMS.mask_for(u, tmask)
        t = _choose(lg["target"][u], tmask)
        if _STICKY:
            t = _MEM.choose(obs, player, u, t, pos[u])
        if _NOIDLE:
            cur = pos[u][1] * 10 + pos[u][0]
            t2 = _pick_working(t, cur, lg["op"][u], lg["target"][u],
                               tmask, tile_bits, unit_bits[u])
            if t2 != t:
                t = t2
                if _STICKY and t != cur:
                    _MEM.tgt[u] = t
        if _AR:
            _CLAIMS.claim(u, t)
        _COLLIDE["units"] += 1
        if t not in _SPEC["SHED_FLAT"]:
            if t in seen_t:
                _COLLIDE["dup"] += 1
            seen_t[t] = u
        o = _choose(lg["op"][u], _op_mask(obs, player, u, t))
        if _GUARDS:
            o = _guard_unit_op(o, obs, player, n, thirsty)
        it = _choose(lg["item"][u], _item_mask(obs, player, u, t, o))
        q = _choose(lg["qty"][u], _qty_mask(obs, player, u, t, o, it))
        heads["target"][u] = t
        heads["op"][u] = o
        heads["item"][u] = it
        heads["qty"][u] = q
    if _MARKET_HEAD == "cand":
        # decode once with an empty slate to learn what the units do to the
        # shed, run the AR loop against that, then decode for real
        heads["market_op"] = [0] * _MARKET_SLOTS
        heads["market_item"] = [0] * _MARKET_SLOTS
        heads["market_qty"] = [0] * _MARKET_SLOTS
        dry = _decode(obs, player, heads)
        prims = [dry["farmer"]] + list(dry["hands"])
        slate = _market_cand_slate(obs, player, lg["mkt_ctx"], prims)
        heads["market_op"] = [x[0] for x in slate]
        heads["market_item"] = [x[1] for x in slate]
        heads["market_qty"] = [x[2] for x in slate]
        return _decode(obs, player, heads)
    for s in range(_MARKET_SLOTS):
        mo = _choose(lg["market_op"][s], masks["market_op"][s])
        if _GUARDS:
            mo = _guard_market_op(mo, obs, player, animals,
                                  obs["farms"][player].get("money", 0.0))
        mi = _choose(lg["market_item"][s], _mkt_item_mask(obs, player, mo))
        mq = _choose(lg["market_qty"][s], _mkt_qty_mask(obs, player, mo, mi))
        heads["market_op"].append(mo)
        heads["market_item"].append(mi)
        heads["market_qty"].append(mq)
    return _decode(obs, player, heads)


def agent(obs):
    _STATS["calls"] += 1
    t0 = _time.perf_counter()
    try:
        out = _play(obs)
    except Exception as _e:
        _STATS["fails"] += 1
        _STATS["last_error"] = repr(_e)
        if _STRICT:
            raise
        out = dict(_PASS)
    _STATS["ms"] += (_time.perf_counter() - t0) * 1000.0
    return out
